  if (!pass) return { score: 0, label: '', color: 'bg-gray-200 w-0' };
  if (pass.length < 8) return { score: 1, label: 'Minimal 8 karakter', color: 'bg-red-500 w-1/4', textColor: 'text-red-500' };

